const $=id=>document.getElementById(id);
const ui={label:$('chapterLabel'),scene:$('sceneName'),caption:$('sceneCaption'),eyebrow:$('eyebrow'),title:$('title'),prose:$('prose'),dialogue:$('dialogue'),actions:$('actions'),record:$('recordLabel'),hpText:$('hpText'),hpFill:$('hpFill'),resolveText:$('resolveText'),resolveFill:$('resolveFill'),intel:$('battleIntel'),log:$('combatLog'),save:$('saveText')};
const chapters=[
 {name:'The Reed Gate',place:'The drowned frontier',enemy:'Ashen Standard-Bearer',hp:58,scene:'A gate swallowed by reeds',caption:'Where the river remembers',story:'At Reed Gate, the river runs black beneath a sky of cinders. A hundred refugees crowd the eastern bank while the last imperial soldiers bar the bridge. Among them stands <em>Lan Wei</em>, a young standard-bearer with your old captain’s seal at her throat. The seal was buried with him.',dialogue:'“Captain Shen. I was told you died with the western host. I was told many things.”',aftermath:'The bridge holds. In the hush after steel, Lan tells you the seal carries a second message: a summons to the Moon Pass, written in your brother’s hand—though he has been dead for three years.'},
 {name:'Moon Pass',place:'The mountain of bells',enemy:'The Pale Strategist',hp:76,scene:'A pass beneath a blind moon',caption:'Every bell tolls for someone',story:'The mountain path is lined with bells wrapped in white silk. Not one rings in the wind. At the summit, the masked strategist known as <em>the Pale Fox</em> waits beside an abandoned imperial standard. He speaks your brother’s name before you do—and offers the truth in exchange for your sword.',dialogue:'“Your brother did not betray the realm, Shen Rui. He discovered who profits from its collapse.”',aftermath:'Behind the mask is Minister Qiao, the architect of the war. He admits he forged the three kingdoms’ border edicts—and that your brother died carrying proof to the capital. The proof is a jade tally, now held in the Burning Court.'},
 {name:'The Burning Court',place:'The capital in flames',enemy:'Regent Cao Vey',hp:96,scene:'The last court of a dying age',caption:'At dawn, the old world ends',story:'Beneath the palace eaves, rain hisses on fire. Regent Cao Vey sits alone before the empty throne, the jade tally between his fingers. Outside, three armies wait for a signal to begin the final slaughter. You have one chance to make them listen.',dialogue:'“A realm is not saved by truth,” the regent says. “It is saved by whoever survives to tell it.”'}
];
let game={phase:'intro',chapter:0,hp:100,maxHp:100,resolve:2,maxResolve:3,enemyHp:0,maxEnemy:0,turn:0,enemyIntent:'',honor:0,trust:0,mercy:0,opening:null,log:[],lastEnding:'',sceneMode:'intro'};
const saved=localStorage.getItem('jade-oath-save');
if(saved){try{const data=JSON.parse(saved);if(data&&data.phase&&data.chapter>=0&&data.chapter<=3)game={...game,...data};}catch{}}
function persist(){try{localStorage.setItem('jade-oath-save',JSON.stringify(game));ui.save.textContent='Journey autosaved';}catch{ui.save.textContent='Unsaved journey';}}
function addLog(text){game.log.unshift(text);game.log=game.log.slice(0,5);ui.log.innerHTML=game.log.map(x=>`<div>${x}</div>`).join('');}
function toast(text){const t=$('toast');t.textContent=text;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1900)}
function button(label,sub,fn,kind=''){const b=document.createElement('button');b.className=`choice ${kind}`;b.innerHTML=`<strong>${label}</strong><span>${sub}</span>`;b.onclick=fn;ui.actions.appendChild(b)}
function stats(){ui.hpText.textContent=`${Math.max(0,game.hp)} / ${game.maxHp}`;ui.hpFill.style.width=`${Math.max(0,game.hp)/game.maxHp*100}%`;ui.resolveText.textContent=`${game.resolve} / ${game.maxResolve}`;ui.resolveFill.style.width=`${game.resolve/game.maxResolve*100}%`;ui.record.textContent=`CHAPTER ${Math.min(3,game.chapter)} / 3`;}
function show(){ui.actions.innerHTML='';stats();ui.log.innerHTML=game.log.map(x=>`<div>${x}</div>`).join('');
 if(game.phase==='intro') intro(); else if(game.phase==='story') story(); else if(game.phase==='battle') battle(); else if(game.phase==='aftermath') aftermath(); else ending();
 persist();}
function setScene(name,sub,caption,mode){ui.scene.innerHTML=`${name}<small>${sub}</small>`;ui.caption.textContent=caption;game.sceneMode=mode;}
function intro(){ui.label.innerHTML='<b>PROLOGUE</b> &nbsp;·&nbsp; THE REED GATE';setScene('A vow beneath<br>falling ash','Year of the Broken Seal','The Han realm is burning','intro');ui.eyebrow.textContent='A STORY OF THREE OATHS';ui.title.textContent='When the banners fall';ui.prose.innerHTML='The Han court is gone. Three kingdoms rise from its ashes, each claiming the mandate of heaven. You are <em>Shen Rui</em>, once a captain of the imperial guard, now a nameless sword walking through a land that has forgotten how to be one. On the road to Reed Gate, a familiar seal waits in unfamiliar hands.';ui.dialogue.innerHTML='<span class="speaker">A letter, half-burned</span>“If the realm must break, let it break on a promise we chose ourselves.”';ui.intel.innerHTML='<b>Your oath</b>Three chapters. Every battle has a tell; every choice leaves a mark.';ui.actions.innerHTML='';button('Begin the journey','Step into the smoke at Reed Gate',()=>{game.phase='story';game.chapter=1;show();},'primary');}
function story(){const c=chapters[game.chapter-1];ui.label.innerHTML=`<b>CHAPTER 0${game.chapter}</b> &nbsp;·&nbsp; ${c.name.toUpperCase()}`;setScene(c.scene,c.place,c.caption,'story');ui.eyebrow.textContent=`CHAPTER 0${game.chapter} · THE ROAD AHEAD`;ui.title.textContent=game.chapter===1?'A face from the dead':game.chapter===2?'The price of a true name':'A throne made of ash';ui.prose.innerHTML=c.story;ui.dialogue.innerHTML=`<span class="speaker">${game.chapter===1?'Lan Wei':game.chapter===2?'The Pale Fox':'Regent Cao Vey'}</span>${c.dialogue}`;ui.intel.innerHTML=`<b>Mission</b>${game.chapter===1?'Cross the bridge and keep the refugees alive.':game.chapter===2?'Unmask the strategist and recover the truth.':'End the war before the armies answer the throne.'}`;ui.actions.innerHTML='';
 if(game.chapter===1){button('Hold the bridge','Stand with Lan Wei · +1 honor',()=>beginBattle('honor'),'primary');button('Evacuate the refugees','Protect the helpless · +1 mercy',()=>beginBattle('mercy'));button('Demand the seal','Trust no one · +1 resolve',()=>beginBattle('caution'));}
 else if(game.chapter===2){button('Trust Lan’s account','Give her the benefit of doubt · +1 trust',()=>beginBattle('trust'),'primary');button('Test the strategist','Let steel ask what words cannot',()=>beginBattle('honor'));button('Listen for the bells','Read the mountain before you move · +1 resolve',()=>beginBattle('caution'));}
 else{button('Call the armies to witness','Put the truth before the throne · +1 honor',()=>beginBattle('honor'),'primary');button('Offer the regent a way out','Save a life, if not a kingdom · +1 mercy',()=>beginBattle('mercy'));button('Strike before he can speak','One swift end · +1 resolve',()=>beginBattle('caution'),'danger');}}
function beginBattle(opening){const c=chapters[game.chapter-1];game.opening=opening;game.phase='battle';game.enemyHp=game.maxEnemy=c.hp;game.turn=0;game.resolve=Math.min(game.maxResolve,game.resolve+(opening==='caution'?1:0));if(opening==='honor')game.honor++;if(opening==='mercy')game.mercy++;if(opening==='trust')game.trust++;game.enemyIntent='Assault';game.log=[];addLog(`${c.enemy} steps into reach.`);show();}
function battle(){const c=chapters[game.chapter-1];ui.label.innerHTML=`<b>CHAPTER 0${game.chapter}</b> &nbsp;·&nbsp; DUEL`;setScene(c.scene,c.place,'Steel answers steel','battle');ui.eyebrow.textContent=`DUEL · ROUND ${game.turn+1}`;ui.title.textContent=`${c.enemy} · ${game.enemyHp} resolve`;ui.prose.innerHTML=`${game.turn===0?'The enemy settles into a measured stance. Watch the tell, then choose your answer.':'The duel turns on a breath. Read the next motion and act.'} <em>Assault</em> breaks through an idle guard; <em>Feint</em> punishes a heavy strike; <em>Aim</em> gathers force for the next blow.`;ui.dialogue.innerHTML=`<span class="speaker">Enemy intent</span><span class="intent"><i></i>${game.enemyIntent}</span> — ${intentText(game.enemyIntent)}`;ui.intel.innerHTML=`<b>Opponent · ${c.enemy}</b><div class="stat-line"><span>GUARD</span><span>${game.enemyHp} / ${game.maxEnemy}</span></div><div class="bar"><div class="fill enemy" style="width:${game.enemyHp/game.maxEnemy*100}%"></div></div><p style="margin:9px 0 0">${game.enemyIntent==='Assault'?'A direct strike is coming. Guard or counter decisively.':game.enemyIntent==='Feint'?'A false opening. A heavy attack will be punished.':'The enemy is gathering power. Interrupt or brace.'}</p>`;ui.actions.innerHTML='';button('Quick cut','Fast · 15 damage · safe against a Feint',()=>act('strike'));button('Measured guard','Recover 1 resolve · reduce incoming damage',()=>act('guard'),'primary');button(`Jade counter${game.resolve?'':' · needs resolve'}`,'Spend 1 resolve · 29 damage · stagger',()=>act('skill'),game.resolve?'':'');if(!game.resolve)ui.actions.lastChild.disabled=true,ui.actions.lastChild.style.opacity='.45';}
function intentText(intent){return intent==='Assault'?'a heavy blow aimed at your guard':intent==='Feint'?'a false opening, then a quick cut':'a gathering strike that will land next turn';}
const cycle=['Assault','Feint','Aim'];

