const cycle=['Assault','Feint','Aim'];
function act(move){if(game.phase!=='battle')return;const intent=game.enemyIntent;let damage=0,received=0,note='';if(move==='strike'){damage=intent==='Assault'?20:intent==='Aim'?19:15;received=intent==='Assault'?16:intent==='Aim'?8:10;note=`Your quick cut deals ${damage}.`;if(intent==='Feint')note+=' You slip past the feint.';if(intent==='Aim')note+=' The strike interrupts the enemy’s aim.';}
 if(move==='guard'){game.resolve=Math.min(game.maxResolve,game.resolve+1);damage=0;received=intent==='Assault'?6:intent==='Aim'?18:5;note=`You turn aside the ${intent.toLowerCase()} and recover resolve.`;}
 if(move==='skill'){if(!game.resolve)return;game.resolve--;damage=29;received=intent==='Feint'?22:intent==='Aim'?4:12;note=`Jade counter lands for ${damage} damage.`;if(intent==='Feint')note+=' The false opening catches you mid-lunge.';if(intent==='Aim')note+=' The gathering strike is broken.';}
 game.enemyHp=Math.max(0,game.enemyHp-damage);addLog(note);if(game.enemyHp<=0){addLog(`${chapters[game.chapter-1].enemy} yields.`);game.phase='aftermath';game.hp=Math.min(game.maxHp,game.hp+20);game.resolve=Math.min(game.maxResolve,game.resolve+1);show();toast('Victory · recovered 20 vitality');return;}
 game.hp=Math.max(0,game.hp-received);addLog(`You take ${received} damage.`);if(game.hp<=0){game.phase='defeat';show();return;}game.turn++;game.enemyIntent=cycle[(game.turn)%cycle.length];show();}
function aftermath(){const c=chapters[game.chapter-1];ui.label.innerHTML=`<b>CHAPTER 0${game.chapter}</b> &nbsp;·&nbsp; AFTERMATH`;setScene(c.scene,c.place,'The cost of the vow','story');ui.eyebrow.textContent='AFTER THE CLASH';ui.title.textContent=game.chapter===3?'Before the final word':'The silence after steel';ui.prose.innerHTML=c.aftermath||'The court falls quiet. For a moment, all that remains is the sound of rain on the old roof and the weight of the jade tally in your palm.';ui.dialogue.innerHTML=game.chapter===3?'<span class="speaker">The regent</span>“Then tell me, oathkeeper. What is a kingdom worth?”':`<span class="speaker">Lan Wei</span>“We have come too far to let someone else choose what this means.”`;ui.intel.innerHTML=`<b>Oath remembered</b>Honor ${game.honor} · Trust ${game.trust} · Mercy ${game.mercy}`;ui.actions.innerHTML='';
 if(game.chapter===1){button('Carry the seal together','Believe Lan Wei · +1 trust',()=>advance('trust'),'primary');button('Swear the refugees safe','Let compassion set the course · +1 mercy',()=>advance('mercy'));button('Keep the seal yourself','The burden is yours alone · +1 honor',()=>advance('honor'));}
 else if(game.chapter===2){button('Share the truth with Lan','A secret held together · +1 trust',()=>advance('trust'),'primary');button('Give proof to the people','Let the realm decide · +1 honor',()=>advance('honor'));button('Burn the forged orders','Stop the war before it begins · +1 mercy',()=>advance('mercy'));}
 else{button('Speak the whole truth','Offer the jade tally to all three armies',()=>finish('truth'),'primary');button('Spare the regent, bind him to peace','Choose mercy over vengeance',()=>finish('mercy'));button('Claim the mandate yourself','End the war by force of will',()=>finish('crown'),'danger');}}
function advance(value){if(value==='trust')game.trust++;if(value==='honor')game.honor++;if(value==='mercy')game.mercy++;if(game.chapter>=3){finish(value);return;}game.chapter++;game.phase='story';show();}
